class Solution {
public:
    int minimumOperations(std::vector<int>& nums) {
        int n = nums.size();
        auto get_min_swaps = [&](int target_zero_idx) {
            std::vector<int> target(n);
            if (target_zero_idx == 0) {
                for (int i = 0; i < n; ++i) target[i] = i;
            } else {
                for (int i = 0; i < n; ++i) target[i] = (i + 1) % n;
            }
            std::vector<int> pos(n);
            for (int i = 0; i < n; ++i) pos[nums[i]] = i;
            std::vector<bool> visited(n, false);
            int total_moves = 0;
            for (int i = 0; i < n; ++i) {
                if (visited[i] || nums[i] == target[i]) continue;
                int cycle_length = 0;
                int curr = i;
                bool has_zero = false;
                while (!visited[curr]) {
                    visited[curr] = true;
                    if (nums[curr] == 0) has_zero = true;
                    curr = pos[target[curr]];
                    cycle_length++;
                }
                if (cycle_length > 1) {
                    if (has_zero) total_moves += (cycle_length - 1);
                    else total_moves += (cycle_length + 1);
                }
            }
            return total_moves;
        };
        return std::min(get_min_swaps(0), get_min_swaps(n - 1));
    }
};

